CREATE DATABASE IF NOT EXISTS signal CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE signal;
CREATE TABLE users (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, name VARCHAR(120) NOT NULL, role ENUM('owner','admin','member') NOT NULL DEFAULT 'owner', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE api_keys (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, user_id BIGINT UNSIGNED NOT NULL, provider VARCHAR(40) NOT NULL, encrypted_key TEXT NOT NULL, base_url VARCHAR(500), model VARCHAR(180), status ENUM('connected','error','not_set') NOT NULL DEFAULT 'not_set', last_checked_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY user_provider(user_id,provider), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE videos (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, user_id BIGINT UNSIGNED NOT NULL, url TEXT NOT NULL, brief_text TEXT NOT NULL, length_target VARCHAR(50), language VARCHAR(30), voice_provider VARCHAR(40), voice_id VARCHAR(180), writer_provider VARCHAR(40), look_settings JSON, status VARCHAR(40) NOT NULL DEFAULT 'queued', retention_expires_at DATETIME, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE video_scripts (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, video_id BIGINT UNSIGNED NOT NULL, version INT NOT NULL, beats JSON NOT NULL, checks JSON, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(video_id) REFERENCES videos(id) ON DELETE CASCADE);
CREATE TABLE video_jobs (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, video_id BIGINT UNSIGNED NOT NULL, stage VARCHAR(40) NOT NULL, progress DECIMAL(5,2) DEFAULT 0, live_status_text TEXT, metrics JSON, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(video_id) REFERENCES videos(id) ON DELETE CASCADE);
CREATE TABLE video_assets (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, video_id BIGINT UNSIGNED NOT NULL, type VARCHAR(40) NOT NULL, storage_path TEXT NOT NULL, bytes BIGINT UNSIGNED DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(video_id) REFERENCES videos(id) ON DELETE CASCADE);
CREATE TABLE brief_templates (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, user_id BIGINT UNSIGNED NULL, title VARCHAR(120) NOT NULL, body TEXT NOT NULL, is_builtin BOOLEAN NOT NULL DEFAULT FALSE, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE INDEX idx_videos_user_status ON videos(user_id,status,created_at);
CREATE INDEX idx_scripts_video_version ON video_scripts(video_id,version);
CREATE INDEX idx_jobs_video_stage ON video_jobs(video_id,stage,updated_at);
CREATE INDEX idx_assets_video_type ON video_assets(video_id,type);
